#include "image_core.c"
#include <stdio.h>
#include <stdlib.h>
#include <math.h>
static size_t live,peak;static unsigned checks;static unsigned seed=0x91527;
#define CHECK(X) do{checks++;if(!(X)){fprintf(stderr,"FAIL line%d: %s\n",__LINE__,#X);exit(1);}}while(0)
typedef union{size_t n;long double a;} Header;
static void *allocfn(void*c,size_t n){(void)c;if(n>18*1024*1024-live)return 0;Header*h=malloc(sizeof(*h)+n);if(!h)return 0;h->n=n;live+=n;if(live>peak)peak=live;return h+1;}
static void freefn(void*c,void*p){(void)c;if(!p)return;Header*h=(Header*)p-1;CHECK(live>=h->n);live-=h->n;free(h);}
static unsigned rng(void){seed=1664525*seed+1013904223;return seed;}
static IEFillOptions opts(void){IEFillOptions f={0};f.kind=IE_FILL_RELIEF;f.region=IE_FILL_SELECTION;f.opacity=f.density=100;f.relief_profile=IE_RELIEF_CIRCULAR;f.relief_unit=IE_RELIEF_PERCENT;f.relief_extent=100;f.relief_height=256;f.relief_intensity=200;f.relief_azimuth=359;return f;}
static void until_height(IEJob*j){unsigned n=0;CHECK(j);while(j->stage!=JOB_RELIEF_HEIGHT){CHECK(!ie_job_step(j,1));CHECK(++n<100000);}}
static void finish(IEJob*j){unsigned n=0;int r;CHECK(j);while(!(r=ie_job_step(j,4096)))CHECK(++n<100000);CHECK(r==1);ie_job_destroy(j);}
static void oracle(void){for(int pass=0;pass<80;pass++){IEDoc d;int w=1+(int)(rng()%39),h=1+(int)(rng()%34);CHECK(ie_init(&d,allocfn,freefn,0,w,h));CHECK(ie_new(&d,w,h,0xA5887755));d.current.selection_mask=allocfn(0,w*h);CHECK(d.current.selection_mask);d.current.selection=(IERect){0,0,w,h,1};for(int i=0;i<w*h;i++)d.current.selection_mask[i]=(rng()%100<70)?255:0;d.current.selection_mask[(h/2)*w+w/2]=255;IEFillOptions f=opts();IEJob*j=ie_fill_start(&d,&f);until_height(j);for(int y=j->miny;y<=j->maxy;y++)for(int x=j->minx;x<=j->maxx;x++){int b=mini(mini(x+1,w-x),mini(y+1,h-y)),sq=b*b;for(int yy=0;yy<h;yy++)for(int xx=0;xx<w;xx++)if(!d.current.selection_mask[yy*w+xx]){int dx=xx-x,dy=yy-y,dd=dx*dx+dy*dy;if(dd<sq)sq=dd;}unsigned expected=(unsigned)floor(sqrt((double)sq)*16);CHECK(j->relief[(y-j->miny)*j->relief_w+x-j->minx]==expected);}ie_job_cancel(j);ie_job_destroy(j);ie_destroy(&d);CHECK(!live);}}
static void skinny(void){int dims[][2]={{8192,1},{1,8192},{8192,64},{64,8192},{1400,1400}};for(unsigned k=0;k<sizeof(dims)/sizeof(dims[0]);k++){int w=dims[k][0],h=dims[k][1];IEDoc d;CHECK(ie_init(&d,allocfn,freefn,0,w,h));CHECK(ie_new(&d,w,h,0x93705030));IEFillOptions f=opts();IEJob*j=ie_fill_start(&d,&f);CHECK(j);int result=0;unsigned calls=0;while(!(result=ie_job_step(j,4096)))CHECK(++calls<100000);if(result<0){CHECK(w==1400&&h==1400);for(int i=0;i<w*h;i++)CHECK(d.current.layers[0].pixels[i]==0x93705030);}else{CHECK(result==1);for(int i=0;i<w*h;i++)CHECK((d.current.layers[0].pixels[i]>>24)==0x93);CHECK(ie_undo(&d));for(int i=0;i<w*h;i++)CHECK(d.current.layers[0].pixels[i]==0x93705030);}ie_job_destroy(j);ie_destroy(&d);CHECK(!live);}}
static void identity(void){for(int h=-256;h<=256;h+=256)for(int intensity=0;intensity<=200;intensity+=200){IEDoc d;CHECK(ie_init(&d,allocfn,freefn,0,43,31));CHECK(ie_new(&d,43,31,0));uint32_t expected[43*31];for(int i=0;i<43*31;i++)expected[i]=d.current.layers[0].pixels[i]=rng();IEFillOptions f=opts();f.relief_height=h;f.relief_intensity=intensity;finish(ie_fill_start(&d,&f));for(int i=0;i<43*31;i++){CHECK((d.current.layers[0].pixels[i]>>24)==(expected[i]>>24));if(!h||!intensity||!(expected[i]>>24))CHECK(d.current.layers[0].pixels[i]==expected[i]);}if(h&&intensity){CHECK(ie_undo(&d));CHECK(!memcmp(expected,d.current.layers[0].pixels,sizeof(expected)));}else CHECK(!d.undo_count);ie_destroy(&d);CHECK(!live);}}
int main(void){oracle();skinny();identity();printf("{\"checks\":%u,\"peakModelBytes\":%zu,\"liveAtExit\":%zu,\"passed\":true}\n",checks,peak,live);}
